import{heroes,events,initial,summon,upgrade,power,bondName,win,xpNeeded}from'./game.js';import{World}from'./world.js';
const $=s=>document.querySelector(s),key='moonbound-save-v1';let state;try{state=JSON.parse(localStorage.getItem(key));if(!state||state.version!==1||!state.chars||!state.party?.length)state=initial()}catch{state=initial()}let world,busy=false,returnPage='roster';
function save(){try{localStorage.setItem(key,JSON.stringify(state))}catch{toast('保存できません。ブラウザのストレージ設定を確認してください。')}render()}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function portrait(h,full=false){const curvy=h.id>=18;return`style="background-image:url('assets/${curvy?'portraits-curvy.png':h.id>=12?'portraits-elegant.png':h.id>=6?'portraits-kpop.png':'portraits.png'}');background-size:300% ${curvy&&!full?400:200}%;background-position:${h.art%3*50}% ${Math.floor(h.art/3)*(curvy&&!full?66.6667:100)}%"`}
function card(h){const c=state.chars[h.id];return`<button class="charcard ${c?'':'locked'}" data-hero="${h.id}"><div class="portrait" ${portrait(h)}></div><div class="charinfo"><span class="rarity">${h.rarity} · ${h.element.toUpperCase()}</span><h4>${h.name}</h4><small>${h.title}</small><span class="lvl">${c?'Lv. '+c.level+'　絆 '+c.bond:'未加入'}</span></div>${state.party.includes(h.id)?'<span class="partyflag">IN PARTY</span>':''}</button>`}
function render(){for(const[k,v]of Object.entries({gems:state.gems,gold:state.gold,rank:Math.floor(state.wins/3)+1,chapter:String(state.chapter).padStart(2,'0'),recommended:Math.max(1,state.chapter*2-1)}))$('#'+k).textContent=v.toLocaleString();$('#ownedcount').textContent=String(Object.keys(state.chars).length).padStart(2,'0')+' / '+heroes.length;const selected=[...state.party,...Object.keys(state.chars).map(Number).filter(id=>!state.party.includes(id))].slice(0,4);$('#partycards').innerHTML=selected.map(id=>card(heroes[id])).join('')+Array.from({length:4-selected.length},()=>'<button class="charcard emptyslot" data-page="summon"><span>＋</span><div><b>新しい仲間を迎える</b><small>星の召喚へ →</small></div></button>').join('');[state.wins,state.pulls,state.bondUsed].forEach((v,i)=>{$('#missioncheck'+(i+1)).textContent=v?'✓':'○';if(v)$('#mission'+(i+1)).textContent='達成済み · '+v+'回'});$('#questprogress').textContent=state.wins?`勝利 ${state.wins}回 · 次の聖域へ進もう`:'遺跡の守護者を倒し、仲間との絆を深めよう'}
function open(html){$('#modalcontent').innerHTML=html;$('#modal').hidden=false;$('#closemodal').focus()}
function close(){$('#modal').hidden=true;document.querySelector('nav .active')?.focus()}
function page(p){if(busy){toast('戦闘中です。撤退してから開いてください。');return}document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===p));if(p==='home'){close();return}returnPage=p;if(p==='roster')open(`<div class="eyebrow">YOUR VALKYRIES</div><h2>仲間との絆を、力に。</h2><p>2人を編成して冒険へ。先頭の仲間を操作し、2人目と合体技を放ちます。</p><p class="note">所持：強化素材 ${state.materials}個 · 装備 ${state.inventory.length}個 · 全24人 · 日本アイドル系 / K-pop系 / 綺麗系 / グラマラス系</p><div class="grid">${heroes.map(card).join('')}</div><button class="secondary" data-action="inventory">アイテムを見る →</button>`);if(p==='summon')summonPage();if(p==='events')open(`<div class="eyebrow">MOONLIT CHRONICLES</div><h2>月夜のイベント</h2><p>いつでも挑戦できる3つのイベント。初回クリアで特別な仲間が加入します。</p><div class="eventlist">${events.map(e=>`<article class="eventtile"><span class="symbol">${e.symbol}</span><h3>${e.name}</h3><p>${e.desc}</p><small>初回加入：${heroes[e.rewardHero].name}<br>報酬：星晶石 ${e.reward} / 経験値 110<br>難易度 ${'★'.repeat(e.difficulty)} ${state.completed.includes(e.id)?' · 初回クリア済み':''}</small><button class="primary" data-event="${e.id}">挑戦する →</button></article>`).join('')}</div>`)}
function summonPage(){open(`<div class="eyebrow">CELESTIAL SUMMON</div><h2>星が導く、新たな仲間。</h2><p>月の向こうで、あなたを待つ物語がある。</p><div class="summonhero"><div class="portrait" ${portrait(heroes[2])}></div><span class="sigil">✧</span><div class="portrait" ${portrait(heroes[0])}></div></div><div class="summonactions"><button class="secondary" data-pull="1" ${state.gems<300?'disabled':''}>1回召喚　✦ 300</button><button class="primary" data-pull="10" ${state.gems<3000?'disabled':''}>10回召喚　✦ 3,000</button></div><p class="rates">SSR 12% / SR 88% · SSRまで最大 ${30-state.pity}回 · 重複は強化素材3個に変換<br>所持星晶石 ${state.gems.toLocaleString()} · ゲーム内報酬で獲得できます</p>`)}
function detail(id){const h=heroes[id],c=state.chars[id];if(!c){toast('召喚またはイベントで仲間にできます。');return}open(`<div class="detail"><div class="portrait ${h.id>=18?'figure':''}" ${portrait(h,true)}></div><div><div class="eyebrow">${h.rarity} / ${h.element.toUpperCase()}</div><h2>${h.name}</h2><p>${h.title}</p><p style="margin-top:18px">${h.desc}</p><div class="stats"><div><small>LEVEL</small><b>${c.level}</b></div><div><small>攻撃力</small><b>${power(state,id)}</b></div><div><small>絆</small><b>${c.bond}</b></div></div><p>経験値 ${c.xp} / ${xpNeeded(c)} · 武器強化 +${c.weapon}</p><div class="xpbar"><i style="width:${c.xp/xpNeeded(c)*100}%"></i></div><button class="primary" data-upgrade="${id}" ${state.materials<2||state.gold<150?'disabled':''}>武器を強化する</button><p class="note">強化素材2個 ＋ 150ゴールド / 攻撃力 +6<br>所持素材 ${state.materials}個</p><button class="secondary" data-lead="${id}">先頭に編成</button><button class="secondary" data-partner="${id}" ${state.party[0]===id?'disabled':''}>相棒に編成</button><p class="note">${state.party.map(i=>heroes[i].name).join(' ＋ ')}<br>${bondName(heroes[state.party[0]],heroes[state.party[1]??state.party[0]])}</p></div></div>`)}
function help(){open(`<div class="eyebrow">HOW TO PLAY</div><h2>月の世界を、冒険しよう。</h2><p>「冒険を始める」で3Dの聖域へ。敵に近づいて攻撃し、すべての敵を倒すと勝利です。<br>光るクリスタルに近づくとHPが回復します。戦闘開始時にも全回復します。</p><div class="helpkeys"><div><b>WASD / 矢印</b>移動</div><div><b>Z / クリック</b>近接攻撃</div><div><b>X</b>範囲スキル（4秒）</div><div><b>C</b>絆の合体技（12秒）</div><div><b>SPACE</b>回避・短時間無敵</div><div><b>ドラッグ</b>視点を回転</div></div><p style="margin-top:22px">スマートフォンは戦闘が画面いっぱいに表示されます。左下のスティックで移動し、右下の攻撃を長押しして連続攻撃できます。縦・横どちらの向きでも遊べます。<br>勝利で経験値・石・装備を獲得。レベルアップ時にもアイテムを獲得します。召喚で仲間を集め、編成画面で武器を強化しましょう。</p><p class="note">進行はこのブラウザに自動保存されます。オンライン共有・課金はありません。スマートフォン・PC対応 / WebGL対応ブラウザが必要です。</p>`)}
function start(eventId=null){if(!world){toast('3D描画を初期化できませんでした。WebGL対応ブラウザで開いてください。');return}close();busy=true;document.body.classList.add('playing');$('#worldcopy').hidden=true;$('#hud').hidden=false;world.start({hero:heroes[state.party[0]],attack:power(state,state.party[0]),level:state.chars[state.party[0]].level,difficulty:eventId?events.find(e=>e.id===eventId).difficulty:Math.ceil(state.chapter/2),eventId,bond:bondName(heroes[state.party[0]],heroes[state.party[1]??state.party[0]])});toast(matchMedia('(pointer: coarse)').matches?'左スティックで移動。右の攻撃ボタンは長押しできます！':'敵に近づいて Z で攻撃。X は範囲攻撃、C は合体技！')}
function finish(victory,eventId){busy=false;document.body.classList.remove('playing');$('#worldcopy').hidden=false;$('#hud').hidden=true;if(!victory){open('<div class="reward"><div class="eyebrow">THE JOURNEY CONTINUES</div><h2>月の光は、まだ消えない。</h2><p>仲間の武器を強化し、回避や合体技を使って再挑戦しよう。<br>撤退・敗北では所持アイテムを失いません。</p><button class="primary" data-retry="'+(eventId??'story')+'">もう一度挑戦する</button><button class="secondary" data-page="roster">育成する</button></div>');return}const r=win(state,eventId);save();open(`<div class="reward"><div class="eyebrow">THE MOON BLESSES YOU</div><h2 class="victory">VICTORY</h2><p>仲間と共に、月影を乗り越えた。</p><div class="rewarditems"><div>✦ ${r.gems}<small>星晶石</small></div><div>◈ ${r.gold}<small>ゴールド</small></div><div>＋${r.xp}<small>経験値 / 各仲間</small></div></div><p>${r.leveled.map(l=>heroes[l.id].name+(l.levels?`：Lv.${state.chars[l.id].level} にレベルアップ！ アイテム獲得`:'：経験値獲得')).join('<br>')}<br>装備「守護者の銀剣」＋ 強化素材3個を獲得${r.unlocked!==null?'<br>新しい仲間「'+heroes[r.unlocked].name+'」が加入！':''}</p><button class="primary" data-page="home">冒険に戻る →</button><button class="secondary" data-page="roster">編成・育成</button></div>`)}
function action(a){if(a==='inventory'){open(`<div class="eyebrow">INVENTORY</div><h2>冒険の戦利品</h2><p>強化素材 ${state.materials}個 · ゴールド ${state.gold}</p><p style="margin-top:20px">${state.inventory.length?state.inventory.slice(-30).map(x=>`◈ ${x.name}　等級 ${x.level}`).join('<br>'):'まだアイテムがありません。冒険で敵を倒そう。'}</p><p class="note">戦利品はコレクションとして保管。武器は強化素材で強化できます。</p>`);return}if(busy)world.action(a)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page)page(b.dataset.page);if(b.dataset.hero)detail(Number(b.dataset.hero));if(b.dataset.pull){const results=summon(state,Number(b.dataset.pull));if(!results)return;save();open(`<div class="eyebrow">YOUR NEW DESTINY</div><h2>星が紡いだ出会い</h2><div class="pulls">${results.map((r,i)=>`<article class="pull" style="animation-delay:${i*.06}s"><div class="portrait" ${portrait(r.hero)}></div><h4>${r.hero.name}</h4><small>${r.hero.rarity} · ${r.duplicate?'重複 → 素材 ＋3':'NEW 仲間に加入'}</small></article>`).join('')}</div><button class="primary" data-page="roster">仲間を見る →</button><button class="secondary" data-page="summon">召喚に戻る</button>`)}if(b.dataset.upgrade){const id=Number(b.dataset.upgrade);if(upgrade(state,id)){save();detail(id);toast('武器を強化！ 攻撃力 +6')}}if(b.dataset.lead){const id=Number(b.dataset.lead),old=state.party[0];state.party=[id,state.party.find(x=>x!==id)??old];save();detail(id);world?.previewHero(heroes[id]);world?.previewPartner(heroes[state.party[1]]);toast('先頭の仲間を変更しました')}if(b.dataset.partner){state.party[1]=Number(b.dataset.partner);save();detail(Number(b.dataset.partner));world?.previewPartner(heroes[state.party[1]]);toast('相棒を変更しました')}if(b.dataset.event)start(b.dataset.event);if(b.dataset.retry)start(b.dataset.retry==='story'?null:b.dataset.retry);if(b.dataset.action)action(b.dataset.action)});
$('#start').onclick=()=>start();$('#help').onclick=help;$('#storyhelp').onclick=()=>open('<div class="eyebrow">CHAPTER 01</div><h2>月に選ばれし者</h2><p>月蝕の夜、古い聖域の封印が解けた。<br>月の加護を受けた騎士セレーネは、炎の魔女イグニスと共に、闇に覆われた遺跡へ向かう。<br><br>対立する氷と炎。けれど、互いを信じた時、その力はひとつになる。<br>失われた星時計、仮面に隠された秘密、紅蓮の誓い。<br>あなたが出会う仲間たちと、新しい運命を切り開こう。</p><button class="primary" data-page="home">冒険へ →</button>');$('#closemodal').onclick=close;$('#modal').onclick=e=>{if(e.target===$('#modal'))close()};$('#exit').onclick=()=>{world.stop();finish(false,world.eventId)};$('#camera').onclick=()=>world?.toggleCamera();$('.brand').onclick=e=>{e.preventDefault();page('home')};$('#settings').onclick=()=>open('<div class="eyebrow">SAVE DATA</div><h2>冒険の記録</h2><p>このブラウザに自動保存しています。別の端末に移す場合は、セーブを書き出してください。</p><button class="primary" id="exportSave">セーブを書き出す</button><button class="secondary" id="importSave">セーブを読み込む</button><input id="savefile" type="file" accept="application/json" hidden><p class="note">現在：勝利 '+state.wins+'回 / 仲間 '+Object.keys(state.chars).length+'人</p>');
document.addEventListener('click',e=>{if(e.target.id==='exportSave'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state)],{type:'application/json'}));a.download='moonbound-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}if(e.target.id==='importSave')$('#savefile').click()});document.addEventListener('change',async e=>{if(e.target.id==='savefile'){try{const s=JSON.parse(await e.target.files[0].text());if(s.version!==1||!Array.isArray(s.party)||s.party.length!==2||!s.party.every(id=>Number.isInteger(id)&&heroes[id]&&s.chars[id])||!['gems','gold','materials','wins','chapter'].every(k=>Number.isFinite(s[k])&&s[k]>=0)||!Array.isArray(s.completed)||!Array.isArray(s.inventory)||!Object.values(s.chars).every(c=>Number.isFinite(c.level)&&c.level>=1&&c.level<=50&&Number.isFinite(c.xp)&&c.xp>=0))throw Error();state=s;save();close();toast('セーブを読み込みました')}catch{toast('有効なセーブファイルを選んでください')}}});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#modal').hidden)close();if(busy&&[' ','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))e.preventDefault()});render();try{world=new World($('#scene'),{finish,onBond:()=>{state.bondUsed++;save()},hud:(hp,max,left,cooldowns)=>{$('#hpbar').style.width=hp/max*100+'%';$('#hptext').textContent=`HP ${Math.ceil(hp)} / ${max}`;$('#battleName').textContent=heroes[state.party[0]].name;$('#enemycount').textContent=`聖域の影　残り ${left}体`;$('#skillcd').textContent=cooldowns.skill>0?Math.ceil(cooldowns.skill):'';$('#bondcd').textContent=cooldowns.bond>0?Math.ceil(cooldowns.bond):''},fx:t=>{$('#fxlabel').textContent=t;$('#fxlabel').classList.add('show');clearTimeout(action.timer);action.timer=setTimeout(()=>$('#fxlabel').classList.remove('show'),1800)}});world.previewHero(heroes[state.party[0]]);world.previewPartner(heroes[state.party[1]])}catch(e){console.error(e);toast('3D描画にはWebGLが必要です。対応ブラウザでお試しください。')}
